package edu.pearlmart;
import org.junit.jupiter.api.*;
import static org.junit.jupiter.api.Assertions.*;
import static edu.pearlmart.Domain.*;
import java.math.BigDecimal;
import java.time.LocalDate;

class WorkflowTest {
 InMemoryStore store; InventoryService inv; SalesService sales;
 @BeforeEach void setup(){store=new InMemoryStore();inv=new InventoryService(store);sales=new SalesService(store,new NoAdjustmentPricing());}
 Item item(String id,int qty){return new Item(id,"BC"+id,"Item "+id,new BigDecimal("10.00"),qty,"Maker","Qatar",null,"");}
 String draft(int q){inv.addNew(item("A",10));String s=sales.start().id();sales.addLine(s,"A",q);return s;}
 @Test void T01_newItemCreatesOneMovement(){inv.addNew(item("A",10));assertEquals(10,inv.find("A").quantity());assertEquals(1,store.snapshot().movements().size());assertEquals(10,store.snapshot().movements().getFirst().delta());}
 @Test void T02_existingItemIncreasesSharedStock(){inv.addNew(item("A",10));inv.addExisting("BCA",5);assertEquals(15,inv.find("A").quantity());assertEquals(2,store.snapshot().movements().size());String s=sales.start().id();assertDoesNotThrow(()->sales.addLine(s,"A",15));}
 @Test void T03_nonpositiveAdditionRejected(){inv.addNew(item("A",10));var before=store.snapshot();for(int q:new int[]{0,-1})assertThrows(IllegalArgumentException.class,()->inv.addExisting("A",q));assertEquals(before,store.snapshot());}
 @Test void T04_duplicateIdentificationRejected(){inv.addNew(item("A",10));var before=store.snapshot();assertThrows(IllegalArgumentException.class,()->inv.addNew(item("A",3)));assertThrows(IllegalArgumentException.class,()->inv.addNew(new Item("B","BCA","B",new BigDecimal("1.00"),2,"M","Q",null,"")));assertEquals(before,store.snapshot());}
 @Test void T05_missingMandatoryFieldRejected(){assertThrows(IllegalArgumentException.class,()->new Item("A","BCA","",new BigDecimal("1.00"),2,"M","Q",null,""));assertTrue(store.snapshot().items().isEmpty());}
 @Test void T06_additionCommitFailureLeavesNoChanges(){inv.addNew(item("A",10));var before=store.snapshot();store.setBeforeCommit(()->{throw new IllegalStateException("Injected commit failure");});assertThrows(IllegalStateException.class,()->inv.addExisting("A",2));assertEquals(before,store.snapshot());}
 @Test void T07_multilineSaleReceiptAndStock(){inv.addNew(item("A",10));inv.addNew(item("B",5));String s=sales.start().id();sales.addLine(s,"A",2);sales.addLine(s,"B",1);var r=sales.confirm(s);assertEquals(new BigDecimal("30.00"),r.totals().payable());assertEquals(8,inv.find("A").quantity());assertEquals(4,inv.find("B").quantity());assertEquals(4,store.snapshot().movements().size());assertEquals(Status.COMPLETED,sales.get(s).status());assertEquals(2,r.lines().size());assertTrue(r.text().contains("TOTAL: 30.00"));}
 @Test void T08_unknownItemRejected(){String s=sales.start().id();var before=store.snapshot();assertThrows(IllegalArgumentException.class,()->sales.addLine(s,"MISSING",1));assertEquals(before,store.snapshot());}
 @Test void T09_invalidAndInsufficientSaleQuantity(){String s=draft(1);var before=store.snapshot();for(int q:new int[]{0,-1,10})assertThrows(IllegalArgumentException.class,()->sales.addLine(s,"A",q));assertEquals(before,store.snapshot());}
 @Test void T10_cancelPreservesStockAndRecordsCancellation(){String s=draft(2);var before=store.snapshot();sales.cancel(s);assertEquals(Status.CANCELLED,sales.get(s).status());assertEquals(before.items(),store.snapshot().items());assertEquals(before.movements(),store.snapshot().movements());assertTrue(store.snapshot().receipts().isEmpty());}
 @Test void T11_confirmTwiceNeverDeductsTwice(){String s=draft(2);sales.confirm(s);var before=store.snapshot();assertThrows(IllegalStateException.class,()->sales.confirm(s));assertEquals(before,store.snapshot());assertEquals(8,inv.find("A").quantity());}
 @Test void T12_finalizationFailureLeavesDraftAndStock(){String s=draft(2);var before=store.snapshot();store.setBeforeCommit(()->{throw new IllegalStateException("Injected failure");});assertThrows(IllegalStateException.class,()->sales.confirm(s));assertEquals(before,store.snapshot());}
 @Test void T13_stockRecheckedBeforeCommitWithoutPartialDeduction(){inv.addNew(item("A",10));inv.addNew(item("B",1));String first=sales.start().id();sales.addLine(first,"A",2);sales.addLine(first,"B",1);String other=sales.start().id();sales.addLine(other,"B",1);sales.confirm(other);var before=store.snapshot();assertThrows(IllegalArgumentException.class,()->sales.confirm(first));assertEquals(before,store.snapshot());assertEquals(10,inv.find("A").quantity());}
 @Test void T14_discountThenTaxPolicy(){String s=draft(2);SalesService adjusted=new SalesService(store,new PercentagePricing(new BigDecimal("0.10"),new BigDecimal("0.05")));var t=adjusted.calculate(s);assertEquals(new BigDecimal("20.00"),t.subtotal());assertEquals(new BigDecimal("2.00"),t.discount());assertEquals(new BigDecimal("0.90"),t.tax());assertEquals(new BigDecimal("18.90"),adjusted.confirm(s).totals().payable());}
 @Test void T15_emptySaleCannotComplete(){String s=sales.start().id();assertThrows(IllegalArgumentException.class,()->sales.calculate(s));assertThrows(IllegalArgumentException.class,()->sales.confirm(s));assertEquals(Status.PENDING,sales.get(s).status());}
 @Test void T16_completedSaleCannotCancel(){String s=draft(2);sales.confirm(s);var before=store.snapshot();assertThrows(IllegalStateException.class,()->sales.cancel(s));assertEquals(before,store.snapshot());}
 @Test void T17_receiptRetrievalHasNoStockEffect(){String s=draft(2);var r=sales.confirm(s);var before=store.snapshot();assertEquals(r,sales.receipt(s));assertEquals(before,store.snapshot());}
 @Test void T18_duplicateLinesAggregateAgainstAvailableStock(){String s=draft(6);sales.addLine(s,"BCA",4);assertEquals(1,sales.get(s).lines().size());assertEquals(10,sales.get(s).lines().getFirst().quantity());assertThrows(IllegalArgumentException.class,()->sales.addLine(s,"A",1));sales.confirm(s);assertEquals(0,inv.find("A").quantity());}
 @Test void T19_cancellationFailureDoesNotChangeState(){String s=draft(2);var before=store.snapshot();store.setBeforeCommit(()->{throw new IllegalStateException("Injected failure");});assertThrows(IllegalStateException.class,()->sales.cancel(s));assertEquals(before,store.snapshot());}
 @Test void T20_builderRejectsPendingSale(){String s=draft(1);assertThrows(IllegalArgumentException.class,()->new SalesReceipt.Builder().fromCompletedSale(sales.get(s)));assertThrows(IllegalStateException.class,()->new SalesReceipt.Builder().build());}
 @Test void T21_invalidPolicyRejected(){assertThrows(IllegalArgumentException.class,()->new PercentagePricing(new BigDecimal("1.01"),BigDecimal.ZERO));}
 @Test void T22_exactStockBoundaryAndPriceSnapshot(){String s=draft(10);var line=sales.get(s).lines().getFirst();inv.addExisting("A",1);assertEquals(new BigDecimal("10.00"),line.unitPrice());sales.confirm(s);assertEquals(1,inv.find("A").quantity());}
 @Test void T23_removeLineLeavesStockUntouched(){String s=draft(2);sales.removeLine(s,"A");assertTrue(sales.get(s).lines().isEmpty());assertEquals(10,inv.find("A").quantity());}
 @Test void T24_expiredItemRejected(){inv.addNew(new Item("A","BCA","Expired",new BigDecimal("1.00"),3,"M","Q",LocalDate.now().minusDays(1),""));String s=sales.start().id();assertThrows(IllegalArgumentException.class,()->sales.addLine(s,"A",1));assertEquals(3,inv.find("A").quantity());}
 @Test void T25_roundingHalfUp(){var p=new PercentagePricing(new BigDecimal("0.10"),new BigDecimal("0.05"));var t=p.calculate(java.util.List.of(new SaleLine("A","A",new BigDecimal("0.05"),1)));assertEquals(new BigDecimal("0.01"),t.discount());assertEquals(new BigDecimal("0.00"),t.tax());assertEquals(new BigDecimal("0.04"),t.payable());}

 @Test void T26_transactionInheritanceAndActorLinks(){String id=draft(2);Transaction t=sales.get(id);assertEquals(User.SALES,t.recordedBy());assertTrue(t.getSummary().contains("PENDING"));sales.confirm(id);var state=store.snapshot();Transaction movement=state.movements().getLast();assertInstanceOf(StockMovement.class,movement);assertEquals(User.SALES,movement.recordedBy());assertEquals(id,state.movements().getLast().reference());assertTrue(sales.get(id).getSummary().contains("COMPLETED"));}
 @Test void T27_addAndCompleteActivityRecordsAreAtomic(){String id=draft(2);assertEquals("ADD_GOODS",store.snapshot().activities().getFirst().action());int count=store.snapshot().activities().size();sales.confirm(id);var activity=store.snapshot().activities().getLast();assertEquals(count+1,store.snapshot().activities().size());assertEquals("SALE_COMPLETED",activity.action());assertEquals(id,activity.recordRef());assertEquals(User.SALES,activity.recordedBy());}
 @Test void T28_cancelRecordsActorReasonWithoutStockMovement(){String id=draft(2);int count=store.snapshot().movements().size();sales.cancel(id);assertFalse(sales.get(id).cancellationReason().isBlank());assertEquals("SALE_CANCELLED",store.snapshot().activities().getLast().action());assertEquals(count,store.snapshot().movements().size());assertEquals(10,inv.find("A").quantity());}
 @Test void T29_itemOwnsStockAndPriceRules(){Item a=item("A",3);assertFalse(a.removeStock(4));assertEquals(3,a.quantity());assertTrue(a.removeStock(3));assertEquals(0,a.quantity());assertThrows(IllegalArgumentException.class,()->a.addStock(0));assertThrows(IllegalArgumentException.class,()->a.updatePrice(new BigDecimal("-1")));assertEquals(new BigDecimal("10.00"),a.price());a.addStock(2);assertTrue(a.hasStock(2));}
 @Test void T30_externalReferencesCannotMutateCommittedState(){Item a=item("A",10);inv.addNew(a);var before=store.snapshot();a.removeStock(5);inv.find("A").removeStock(2);store.snapshot().items().get("A").removeStock(1);assertEquals(before,store.snapshot());String id=sales.start().id();sales.addLine(id,"A",2);sales.get(id).cancel("Detached copy");assertEquals(Status.PENDING,sales.get(id).status());assertEquals(10,inv.find("A").quantity());}
 @Test void T31_roleChecksRejectWrongWorkflowWithoutWrites(){var before=store.snapshot();InventoryService wrongInv=new InventoryService(store,User.SALES);assertThrows(SecurityException.class,()->wrongInv.addNew(item("A",2)));SalesService wrongSale=new SalesService(store,new NoAdjustmentPricing(),User.INVENTORY);assertThrows(SecurityException.class,wrongSale::start);assertEquals(before,store.snapshot());}
 @Test void T32_priceSnapshotSurvivesItemPriceChange(){Item a=item("A",10);Sale s=new Sale("S",java.time.Instant.now(),User.SALES);s.addLine(a,2);a.updatePrice(new BigDecimal("99.00"));s.calculateTotal(new NoAdjustmentPricing());assertEquals(new BigDecimal("20.00"),s.totals().payable());assertEquals(new BigDecimal("10.00"),s.lines().getFirst().unitPrice());}
 @Test void T33_saleLifecycleAndOwnedLinesCannotBeBypassed(){Item a=item("A",3);Sale s=new Sale("S",java.time.Instant.now(),User.SALES);assertThrows(IllegalStateException.class,s::complete);s.addLine(a,2);assertThrows(UnsupportedOperationException.class,()->s.lines().clear());s.calculateTotal(new NoAdjustmentPricing());assertTrue(s.complete());assertThrows(IllegalStateException.class,()->s.addLine(a,1));assertThrows(IllegalStateException.class,()->s.cancel("Too late"));}
 @Test void T34_inventoryOverflowLeavesRecordsUnchanged(){inv.addNew(item("A",Integer.MAX_VALUE));var before=store.snapshot();assertThrows(ArithmeticException.class,()->inv.addExisting("A",1));assertEquals(before,store.snapshot());}
}
